/**
 * Where the workspace's human layer lives.
 *
 * The evidence layer (opportunities, facts, gates) is generated by the workers
 * and shipped as data. The HUMAN layer — review decisions, project tags, notes,
 * tasks, contacts, saved views — is written in the browser, because the console
 * is a static export with no backend of its own.
 *
 * That is a real limitation, not a design preference, so it is named rather
 * than hidden: `durability` tells the UI what to tell the operator, and the
 * driver interface is deliberately the smallest thing a Supabase-backed store
 * could implement unchanged the day authentication comes back.
 */

export type StorageDurability =
  /** This browser only. Clearing site data loses it; a second device never sees it. */
  | "BROWSER_LOCAL"
  /** Kept on a server, per authenticated user. */
  | "SERVER"
  /** This page view only (SSR, tests). */
  | "EPHEMERAL";

export interface WorkspaceStore {
  readonly driver: string;
  readonly durability: StorageDurability;
  read<T>(key: string, fallback: T): T;
  write(key: string, value: unknown): void;
  /** Every key this store holds — used by the backup export. */
  keys(): string[];
}

/** Keys the workspace owns. A backup is exactly these. */
export const WORKSPACE_KEYS = [
  "oia.audit.v1",
  "oia.views.v1",
  "oia.tags.v1",
  "oia.notes.v1",
  "oia.tasks.v1",
  "oia.contacts.v1",
] as const;

/** In-memory store: server rendering, tests, and the fallback when storage throws. */
export function createMemoryStore(seed: Record<string, unknown> = {}): WorkspaceStore {
  const map = new Map<string, unknown>(Object.entries(seed));
  return {
    driver: "memory",
    durability: "EPHEMERAL",
    read<T>(key: string, fallback: T): T {
      return map.has(key) ? (map.get(key) as T) : fallback;
    },
    write(key: string, value: unknown) {
      map.set(key, value);
    },
    keys: () => [...map.keys()],
  };
}

/** The part of the Web Storage API this package uses (keeps it DOM-free). */
export interface StorageLike {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}

/**
 * Web-storage driver. The caller passes `window.localStorage` (or nothing, on
 * the server, where it falls back to memory). Every access is guarded: quota
 * errors, disabled storage and private-mode throws must degrade to "the UI
 * still works, persistence doesn't", never to a blank screen.
 */
export function createLocalStorageStore(storage?: StorageLike | null): WorkspaceStore {
  if (!storage) return createMemoryStore();
  return {
    driver: "localStorage",
    durability: "BROWSER_LOCAL",
    read<T>(key: string, fallback: T): T {
      try {
        const raw = storage.getItem(key);
        return raw ? (JSON.parse(raw) as T) : fallback;
      } catch {
        return fallback;
      }
    },
    write(key: string, value: unknown) {
      try {
        storage.setItem(key, JSON.stringify(value));
      } catch {
        // Quota or blocked storage: best-effort by design.
      }
    },
    keys: () => [...WORKSPACE_KEYS],
  };
}

// ── Backup / restore ─────────────────────────────────────────────────────────

export interface WorkspaceBackup {
  kind: "oia.workspace.backup";
  version: 1;
  exportedAt: string;
  driver: string;
  data: Record<string, unknown>;
}

/** Everything the human layer holds, as one portable file. */
export function exportWorkspace(store: WorkspaceStore, nowIso: string): WorkspaceBackup {
  const data: Record<string, unknown> = {};
  for (const key of WORKSPACE_KEYS) data[key] = store.read(key, null);
  return { kind: "oia.workspace.backup", version: 1, exportedAt: nowIso, driver: store.driver, data };
}

export interface RestoreResult {
  restored: string[];
  skipped: string[];
}

/**
 * Restore a backup. Unknown keys are skipped rather than trusted, and the audit
 * log is MERGED, never replaced: the trail is append-only, and importing an
 * older file must not erase decisions taken since.
 */
export function importWorkspace(store: WorkspaceStore, backup: unknown): RestoreResult {
  const result: RestoreResult = { restored: [], skipped: [] };
  const b = backup as Partial<WorkspaceBackup> | null;
  if (!b || b.kind !== "oia.workspace.backup" || !b.data) {
    throw new Error("not an OIA workspace backup");
  }

  for (const [key, value] of Object.entries(b.data)) {
    if (!(WORKSPACE_KEYS as readonly string[]).includes(key) || value === null) {
      result.skipped.push(key);
      continue;
    }
    if (key === "oia.audit.v1" && Array.isArray(value)) {
      const current = store.read<{ id: string }[]>(key, []);
      const seen = new Set(current.map((e) => e.id));
      const merged = [...current, ...(value as { id: string }[]).filter((e) => !seen.has(e.id))];
      merged.sort((a, b2) => String((a as { at?: string }).at).localeCompare(String((b2 as { at?: string }).at)));
      store.write(key, merged);
    } else {
      store.write(key, value);
    }
    result.restored.push(key);
  }
  return result;
}
